const byOrder=(a,b)=>a.order-b.order;
const find=(p,id)=>p.entities.find(e=>e.id===id);
const getChapter=(p,e)=>{let n=e;const visited=new Set();while(n&&!visited.has(n.id)){if(n.type==='chapter')return n;visited.add(n.id);n=find(p,n.parentId)}return null};
