 const mediaSignature=p.entities.filter(e=>mediaKinds.includes(e.type)&&e.data.fileId).map(e=>e.id+':'+e.data.fileId+':'+!!e.data.missingFile).join('|');
 useEffect(()=>{let alive=true,checking=false;const audit=async()=>{if(checking)return;checking=true;try{const snapshot=store.getState().project;if(snapshot.id!==p.id)return;const missing=new Set(await findMissingFileIds(snapshot));if(!alive||store.getState().project.id!==snapshot.id)return;for(const e of snapshot.entities){if(!mediaKinds.includes(e.type)||!e.data.fileId)continue;const current=find(store.getState().project,e.id);if(current?.data.fileId!==e.data.fileId)continue;const absent=missing.has(e.data.fileId);if(!!current.data.missingFile!==absent)store.updateEntity(e.id,{data:{missingFile:absent}})}}catch{if(alive)store.notify(t('story.copy42'))}finally{checking=false}};audit();window.addEventListener('focus',audit);return()=>{alive=false;window.removeEventListener('focus',audit)}},[p.id,mediaSignature]);
