 const inspect=id=>{store.select(id);const live=store.getState().project,e=find(live,id),c=getChapter(live,e);if(c)store.setScope(c.id);if(e&&['character','location',...mediaKinds].includes(e.type)&&state.mode==='guide'&&state.section!=='journey')store.setSection(e.type==='character'?'characters':e.type==='location'?'locations':'assets')};
 const showActivity=()=>{store.setMode('guide');store.setSection('activity');store.select(null);onSidebarView('story');};
