 const remove=id=>{const e=find(p,id);if(e)open({type:'delete',id})};
 const connect=(source='',target='')=>open({type:'connect',source,target});
 useEffect(()=>{if(!state.notice)return;const t=setTimeout(()=>store.notify(''),5500);return()=>clearTimeout(t)},[state.notice]);
 useEffect(()=>{const handler=e=>{const editing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if(e.key==='Escape'&&!modal)store.select(null);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearch('');open({type:'search'})}if(!editing&&!modal&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?store.redo():store.undo()}if(!editing&&!modal&&e.key==='?')open({type:'help'})};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[modal]);
