 {sidebarView==='library'?<a className="brand" href="/" onClick={e=>{e.preventDefault();onSidebarView('library');}}><span className="brand-mark">Ⅱ</span><b>{t('app.name')}</b><span className="brand-sub">STUDIO</span></a>:<><button className="story-home-back" onClick={()=>onSidebarView('library')}><ChevronLeft size={17}/>{t('nav.library')}</button><RecentStoriesDropdown state={state} onOpenCloud={()=>open({type:'cloud'})} onOpenLocal={()=>open({type:'projects'})} onSelect={()=>{openStoryboard();onSidebarView('story',{selected:true});}}/><div className="view-switch" role="group" aria-label={t('nav.workspaceMode')}><button data-testid="mode-guide" aria-pressed={storyboardActive} onClick={openStoryboard}><LayoutGrid size={15}/>{t('nav.storyboard')}</button><button data-testid="mode-legacy-guide" aria-pressed={state.mode==='guide'&&state.section==='journey'&&!storyboardActive} onClick={()=>{setLegacyGuide(true);store.setMode('guide');store.setSection('journey');store.select(null);}}>{t('nav.guided')}</button><button data-testid="mode-canvas" aria-pressed={state.mode==='canvas'} onClick={()=>store.setMode('canvas')}><Workflow size={15}/>{t('nav.canvas')}</button></div>{chapterList.length>1&&<select className="story-chapter-select" aria-label={t('nav.chapter')} value={chapter?.id||chapterList[0]?.id} onChange={event=>focusChapter(event.target.value)}>{chapterList.map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select>}</>}
