 <details className="story-account-menu"><summary>{c.account||t('story.copy14')}<ChevronRight size={13}/>{(c.error||c.conflict||c.remoteUpdate||c.draftOffer)&&<span className="story-account-attention" title={t('story.copy50')}>●</span>}</summary><div className="story-account-panel"><p>{c.account?t('story.copy10')+c.account:t('story.copy6')}<small>{t('story.currentWork')}{state.workspace.mode==='cloud'?t('story.copy8'):t('story.copy9')}</small></p><button onClick={()=>open({type:'cloud'})}><FolderOpen size={15}/>{c.account?t('story.copy51'):t('story.copy3')}</button><button onClick={()=>open({type:'project-settings'})}><Settings2 size={15}/>{t('story.copy52')}</button><button disabled={busy} onClick={backup}><Download size={15}/>{t('story.copy53')}</button><button onClick={()=>open({type:'projects'})}><Upload size={15}/>{t('story.copy54')}</button><button onClick={()=>open({type:'agent'})}><Bot size={15}/>{t('story.copy31')}</button><OperatorEntry account={c.account} className="story-menu-link"/><a href="/quick-chat">{t('story.copy55')}</a><button onClick={()=>open({type:'help'})}><HelpCircle size={15}/>{t('story.copy56')}</button>{sidebarView!=='library'&&<><details className="story-more-content"><summary>{t('story.copy57')}</summary>{[['story',t('story.copy58')],['characters',t('story.copy59')],['locations',t('story.copy60')],['assets',t('story.copy61')],['production',t('story.copy62')],['activity',t('story.copy32')]].map(([id,label])=><button key={id} onClick={()=>{store.setMode('guide');store.setSection(id);if(id==='story')store.setScope(null);store.select(null);}}>{label}</button>)}<button onClick={()=>add('chapter')}>{t('story.copy63')}</button><button onClick={()=>connect(selected?.id||'')}>{t('story.copy64')}</button></details><CloudWorkspaceBar onOpenCloud={()=>open({type:'cloud'})}/></>}</div></details>
